"use client"

import * as React from "react"
import { PipetteIcon } from "lucide-react"

import { cn } from "@/registry/default/lib/utils"
import {
  formatHex,
  formatOklch,
  parseHex,
  type Hsva,
} from "@/registry/default/lib/color"
import { useControllableState } from "@/registry/default/hooks/use-controllable-state"
import { Button } from "@/registry/default/ui/button"
import {
  AlphaSlider,
  ColorArea,
  ColorSwatch,
  HueSlider,
} from "@/registry/default/ui/color-picker-controls"
import { Input } from "@/registry/default/ui/input"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/registry/default/ui/popover"

const BLACK: Hsva = { h: 0, s: 0, v: 0, a: 1 }

type EyeDropperConstructor = new () => {
  open: () => Promise<{ sRGBHex: string }>
}

function subscribeToNothing() {
  return () => {}
}

function readEyeDropper() {
  return (window as { EyeDropper?: EyeDropperConstructor }).EyeDropper ?? null
}

function useEyeDropper() {
  return React.useSyncExternalStore(
    subscribeToNothing,
    readEyeDropper,
    () => null
  )
}

function HexInput({
  hex,
  onCommit,
}: {
  hex: string
  onCommit: (hex: string) => void
}) {
  const [draft, setDraft] = React.useState(hex)

  return (
    <Input
      aria-label="Hex color"
      spellCheck={false}
      value={draft}
      aria-invalid={parseHex(draft) ? undefined : true}
      onChange={(event) => setDraft(event.target.value)}
      onBlur={() => onCommit(draft)}
      onKeyDown={(event) => {
        if (event.key === "Enter") onCommit(draft)
      }}
      className="h-8 font-mono text-xs"
    />
  )
}

function ColorPicker({
  value,
  defaultValue = "#000000",
  onValueChange,
  showAlpha = true,
  swatches,
  className,
  ...props
}: Omit<
  React.ComponentProps<typeof Button>,
  "value" | "defaultValue" | "onChange"
> & {
  value?: string
  defaultValue?: string
  onValueChange?: (hex: string) => void
  showAlpha?: boolean
  swatches?: string[]
}) {
  const EyeDropper = useEyeDropper()
  const { value: hex, setValue: setHex } = useControllableState({
    value,
    defaultValue,
    onChange: onValueChange,
  })
  const [hsva, setHsva] = React.useState(() => parseHex(hex) ?? BLACK)
  const [syncedHex, setSyncedHex] = React.useState(hex)

  if (hex !== syncedHex) {
    setSyncedHex(hex)
    if (hex !== formatHex(hsva)) setHsva(parseHex(hex) ?? hsva)
  }

  function updateHsva(next: Hsva) {
    const normalized = showAlpha ? next : { ...next, a: 1 }
    const nextHex = formatHex(normalized)
    setHsva(normalized)
    setSyncedHex(nextHex)
    setHex(nextHex)
  }

  function commitHex(candidate: string) {
    const parsed = parseHex(candidate)
    if (parsed) updateHsva(parsed)
  }

  async function pickFromScreen() {
    if (!EyeDropper) return
    try {
      const { sRGBHex } = await new EyeDropper().open()
      const picked = parseHex(sRGBHex)
      if (picked) updateHsva({ ...picked, a: hsva.a })
    } catch {
      return
    }
  }

  return (
    <Popover>
      <PopoverTrigger asChild>
        <Button
          variant="outline"
          data-slot="color-picker-trigger"
          className={cn("justify-start gap-2 font-mono text-xs", className)}
          {...props}
        >
          <ColorSwatch color={hex} />
          {hex}
        </Button>
      </PopoverTrigger>
      <PopoverContent
        data-slot="color-picker-content"
        align="start"
        className="flex w-64 flex-col gap-3 p-3"
      >
        <ColorArea hsva={hsva} onHsvaChange={updateHsva} />
        <div className="flex items-center gap-3">
          {EyeDropper && (
            <Button
              variant="ghost"
              size="icon"
              aria-label="Pick a color from the screen"
              onClick={pickFromScreen}
              className="size-8"
            >
              <PipetteIcon />
            </Button>
          )}
          <div className="flex flex-1 flex-col gap-3">
            <HueSlider hsva={hsva} onHsvaChange={updateHsva} />
            {showAlpha && <AlphaSlider hsva={hsva} onHsvaChange={updateHsva} />}
          </div>
        </div>
        <HexInput key={hex} hex={hex} onCommit={commitHex} />
        <output className="truncate font-mono text-[11px] text-muted-foreground select-all">
          {formatOklch(hsva)}
        </output>
        {swatches && (
          <div className="grid grid-cols-8 gap-1.5">
            {swatches.map((swatch) => (
              <button
                key={swatch}
                type="button"
                aria-label={`Use ${swatch}`}
                onClick={() => commitHex(swatch)}
                className="rounded-sm outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
              >
                <ColorSwatch color={swatch} className="size-full" />
              </button>
            ))}
          </div>
        )}
      </PopoverContent>
    </Popover>
  )
}

export { ColorPicker }

"use client"

import * as React from "react"
import { Slider as SliderPrimitive } from "radix-ui"

import { cn } from "@/registry/default/lib/utils"
import { clampUnit, formatRgba, type Hsva } from "@/registry/default/lib/color"

const FINE_STEP = 0.01
const COARSE_STEP = 0.1

const CHECKERBOARD =
  "repeating-conic-gradient(#d4d4d4 0% 25%, #fff 0% 50%) 50% / 8px 8px"

const HUE_GRADIENT =
  "linear-gradient(to right, #f00, #ff0, #0f0, #0ff, #00f, #f0f, #f00)"

const thumbClassName =
  "block size-4 rounded-full border-2 border-white shadow-[0_0_0_1px_rgb(0_0_0/0.2),0_1px_3px_rgb(0_0_0/0.3)] outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"

function areaKeyDelta(key: string) {
  switch (key) {
    case "ArrowLeft":
      return { saturation: -1, brightness: 0 }
    case "ArrowRight":
      return { saturation: 1, brightness: 0 }
    case "ArrowUp":
      return { saturation: 0, brightness: 1 }
    case "ArrowDown":
      return { saturation: 0, brightness: -1 }
    default:
      return null
  }
}

function ColorArea({
  hsva,
  onHsvaChange,
  className,
}: {
  hsva: Hsva
  onHsvaChange: (hsva: Hsva) => void
  className?: string
}) {
  const areaRef = React.useRef<HTMLDivElement>(null)
  const thumbRef = React.useRef<HTMLDivElement>(null)

  function updateFromPointer(event: React.PointerEvent<HTMLDivElement>) {
    const rect = areaRef.current?.getBoundingClientRect()
    if (!rect) return
    onHsvaChange({
      ...hsva,
      s: clampUnit((event.clientX - rect.left) / rect.width),
      v: 1 - clampUnit((event.clientY - rect.top) / rect.height),
    })
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    const delta = areaKeyDelta(event.key)
    if (!delta) return
    event.preventDefault()
    const step = event.shiftKey ? COARSE_STEP : FINE_STEP
    onHsvaChange({
      ...hsva,
      s: clampUnit(hsva.s + delta.saturation * step),
      v: clampUnit(hsva.v + delta.brightness * step),
    })
  }

  return (
    <div
      ref={areaRef}
      data-slot="color-area"
      onPointerDown={(event) => {
        event.preventDefault()
        event.currentTarget.setPointerCapture(event.pointerId)
        thumbRef.current?.focus()
        updateFromPointer(event)
      }}
      onPointerMove={(event) => {
        if (event.currentTarget.hasPointerCapture(event.pointerId))
          updateFromPointer(event)
      }}
      style={{
        background: `linear-gradient(to top, #000, transparent), linear-gradient(to right, #fff, transparent), hsl(${hsva.h} 100% 50%)`,
      }}
      className={cn(
        "relative h-40 w-full cursor-crosshair touch-none rounded-md",
        className
      )}
    >
      <div
        ref={thumbRef}
        role="slider"
        tabIndex={0}
        aria-label="Saturation and brightness"
        aria-valuenow={Math.round(hsva.s * 100)}
        aria-valuetext={`Saturation ${Math.round(hsva.s * 100)}%, brightness ${Math.round(hsva.v * 100)}%`}
        onKeyDown={handleKeyDown}
        style={{
          left: `${hsva.s * 100}%`,
          top: `${(1 - hsva.v) * 100}%`,
          background: formatRgba({ ...hsva, a: 1 }),
        }}
        className={cn(thumbClassName, "absolute -translate-1/2")}
      />
    </div>
  )
}

function ColorSlider({
  value,
  max,
  step,
  trackBackground,
  onValueChange,
  "aria-label": ariaLabel,
}: {
  value: number
  max: number
  step: number
  trackBackground: string
  onValueChange: (value: number) => void
  "aria-label": string
}) {
  return (
    <SliderPrimitive.Root
      data-slot="color-slider"
      value={[value]}
      max={max}
      step={step}
      onValueChange={([next]) => onValueChange(next)}
      className="relative flex h-4 w-full touch-none items-center select-none"
    >
      <SliderPrimitive.Track
        style={{ background: trackBackground }}
        className="relative h-3 w-full grow overflow-hidden rounded-full shadow-[inset_0_0_0_1px_rgb(0_0_0/0.1)]"
      />
      <SliderPrimitive.Thumb
        aria-label={ariaLabel}
        className={thumbClassName}
      />
    </SliderPrimitive.Root>
  )
}

function HueSlider({
  hsva,
  onHsvaChange,
}: {
  hsva: Hsva
  onHsvaChange: (hsva: Hsva) => void
}) {
  return (
    <ColorSlider
      aria-label="Hue"
      value={hsva.h}
      max={359}
      step={1}
      trackBackground={HUE_GRADIENT}
      onValueChange={(h) => onHsvaChange({ ...hsva, h })}
    />
  )
}

function AlphaSlider({
  hsva,
  onHsvaChange,
}: {
  hsva: Hsva
  onHsvaChange: (hsva: Hsva) => void
}) {
  const opaque = formatRgba({ ...hsva, a: 1 })

  return (
    <ColorSlider
      aria-label="Opacity"
      value={hsva.a}
      max={1}
      step={FINE_STEP}
      trackBackground={`linear-gradient(to right, transparent, ${opaque}), ${CHECKERBOARD}`}
      onValueChange={(a) => onHsvaChange({ ...hsva, a })}
    />
  )
}

function ColorSwatch({
  color,
  className,
  ...props
}: React.ComponentProps<"span"> & { color: string }) {
  return (
    <span
      data-slot="color-swatch"
      style={{
        background: `linear-gradient(${color}, ${color}), ${CHECKERBOARD}`,
      }}
      className={cn(
        "inline-block size-5 shrink-0 rounded-sm shadow-[inset_0_0_0_1px_rgb(0_0_0/0.15)]",
        className
      )}
      {...props}
    />
  )
}

export { AlphaSlider, ColorArea, ColorSwatch, HueSlider }

export type Hsva = { h: number; s: number; v: number; a: number }
type Rgb = { r: number; g: number; b: number }

const HEX_PATTERN = /^#?([0-9a-f]{3,4}|[0-9a-f]{6}|[0-9a-f]{8})$/i

function roundTo(value: number, digits: number) {
  const factor = 10 ** digits
  return Math.round(value * factor) / factor
}

function toHexByte(channel: number) {
  return Math.round(channel).toString(16).padStart(2, "0")
}

function srgbToLinear(channel: number) {
  const normalized = channel / 255
  if (normalized <= 0.04045) return normalized / 12.92
  return ((normalized + 0.055) / 1.055) ** 2.4
}

export function clampUnit(value: number) {
  return Math.min(1, Math.max(0, value))
}

export function hsvaToRgb({ h, s, v }: Hsva): Rgb {
  const channel = (offset: number) => {
    const k = (offset + h / 60) % 6
    return (v - v * s * Math.max(0, Math.min(k, 4 - k, 1))) * 255
  }
  return { r: channel(5), g: channel(3), b: channel(1) }
}

function rgbToHsv({ r, g, b }: Rgb) {
  const [red, green, blue] = [r / 255, g / 255, b / 255]
  const max = Math.max(red, green, blue)
  const chroma = max - Math.min(red, green, blue)
  const saturation = max === 0 ? 0 : chroma / max
  if (chroma === 0) return { h: 0, s: saturation, v: max }

  let sector = 0
  switch (max) {
    case red:
      sector = ((green - blue) / chroma) % 6
      break
    case green:
      sector = (blue - red) / chroma + 2
      break
    case blue:
      sector = (red - green) / chroma + 4
      break
  }
  return { h: (sector * 60 + 360) % 360, s: saturation, v: max }
}

export function parseHex(value: string): Hsva | null {
  const match = HEX_PATTERN.exec(value.trim())
  if (!match) return null
  const digits = match[1]
  const expanded =
    digits.length <= 4
      ? [...digits].map((digit) => digit + digit).join("")
      : digits
  const byteAt = (index: number) =>
    parseInt(expanded.slice(index * 2, index * 2 + 2), 16)
  const alpha = expanded.length === 8 ? byteAt(3) / 255 : 1
  return { ...rgbToHsv({ r: byteAt(0), g: byteAt(1), b: byteAt(2) }), a: alpha }
}

export function formatHex(hsva: Hsva) {
  const { r, g, b } = hsvaToRgb(hsva)
  const alpha = hsva.a < 1 ? toHexByte(hsva.a * 255) : ""
  return `#${toHexByte(r)}${toHexByte(g)}${toHexByte(b)}${alpha}`
}

export function formatRgba(hsva: Hsva) {
  const { r, g, b } = hsvaToRgb(hsva)
  return `rgb(${Math.round(r)} ${Math.round(g)} ${Math.round(b)} / ${roundTo(hsva.a, 2)})`
}

export function formatOklch(hsva: Hsva) {
  const { r, g, b } = hsvaToRgb(hsva)
  const [red, green, blue] = [srgbToLinear(r), srgbToLinear(g), srgbToLinear(b)]
  const long = Math.cbrt(
    0.4122214708 * red + 0.5363325363 * green + 0.0514459929 * blue
  )
  const medium = Math.cbrt(
    0.2119034982 * red + 0.6806995451 * green + 0.1073969566 * blue
  )
  const short = Math.cbrt(
    0.0883024619 * red + 0.2817188376 * green + 0.6299787005 * blue
  )

  const lightness =
    0.2104542553 * long + 0.793617785 * medium - 0.0040720468 * short
  const greenRed =
    1.9779984951 * long - 2.428592205 * medium + 0.4505937099 * short
  const blueYellow =
    0.0259040371 * long + 0.7827717662 * medium - 0.808675766 * short
  const chroma = Math.hypot(greenRed, blueYellow)
  const hue =
    chroma < 0.0005 ? 0 : (Math.atan2(blueYellow, greenRed) * 180) / Math.PI
  const alpha = hsva.a < 1 ? ` / ${Math.round(hsva.a * 100)}%` : ""

  return `oklch(${roundTo(lightness, 3)} ${roundTo(chroma, 3)} ${roundTo((hue + 360) % 360, 1)}${alpha})`
}
